def min_rotation_cost(c1, c2):
    """Returns the minimum time to rotate from c1 to c2 (not circular)"""
    return abs(ord(c2) - ord(c1))

def solve(names, k):
    # For each position in the string, we want to find the character that minimizes
    # the total rotation cost across all names
    result = []

    for pos in range(k):
        # Collect the letter at position pos from all names
        letters = [name[pos] for name in names]

        # Find the lexicographically smallest character that minimizes total cost
        total_cost = {}

        for c in 'abcdefghijklmnopqrstuvwxyz':
            cost = 0
            for letter in letters:
                cost += min_rotation_cost(letter, c)
            total_cost[c] = cost

        # Find the character with minimal total cost
        min_cost = min(total_cost.values())
        best_char = min([c for c in total_cost if total_cost[c] == min_cost], 
                       key=lambda x: x)  # lexicographically smallest if tie

        result.append(best_char)

    return ''.join(result)

# Read input and solve
